 static void runePlanner()throws Exception{
  Class<?> cls=Class.forName("io.xeros.content.skills.construction.StudyRuneExchange");Method exchange=cls.getDeclaredMethod("exchange",Player.class,int[][].class,int.class);exchange.setAccessible(true);
  int[][] combos={{4694,555,554},{4695,556,555},{4696,556,557},{4697,556,554},{4698,555,557},{4699,557,554}};
  Player p=SkillsAuditCheck.actor();int tested=0;
  for(int[] combo:combos)for(int mask=0;mask<4;mask++){
   bag(p);p.getOutStream().currentOffset=0;give(p,1761,1);give(p,564,1);give(p,combo[0],3);int[][] cost={{1761,1},{564,1},{combo[1],(mask&1)==0?1:3},{combo[2],(mask&2)==0?1:3}};
   ok((Boolean)exchange.invoke(null,p,cost,8016)&&count(p,8016)==1&&count(p,combo[0])==3-Math.max(cost[2][1],cost[3][1]),"Combination substitutes both elements or larger requirement atomically "+combo[0]+"/"+mask);tested++;
  }
  bag(p);give(p,1761,1);give(p,564,1);give(p,4694,1);give(p,4695,1);int[][] cost={{1761,1},{564,1},{554,1},{555,1},{556,1}};ok((Boolean)exchange.invoke(null,p,cost,8016)&&count(p,8016)==1,"Planner avoids greedy elemental dead end");
  bag(p);give(p,1761,1);for(int[] combo:combos)give(p,combo[0],20);int[] before=p.playerItems.clone(),counts=p.playerItemsN.clone();ok(!(Boolean)exchange.invoke(null,p,new int[][]{{1761,1},{564,1},{557,20},{554,20}},8021)&&Arrays.equals(before,p.playerItems)&&Arrays.equals(counts,p.playerItemsN),"Missing cosmic short-circuits combinatorial substitutions with no loss");
  bag(p);give(p,1761,1);give(p,564,1);give(p,555,1);give(p,8016,Integer.MAX_VALUE);before=p.playerItems.clone();counts=p.playerItemsN.clone();ok(!(Boolean)exchange.invoke(null,p,new int[][]{{1761,1},{564,1},{555,1}},8016)&&Arrays.equals(before,p.playerItems)&&Arrays.equals(counts,p.playerItemsN),"Overflowing output cannot consume clay or runes");
  ok(tested==24,"Six combinations four unequal quantity pairs");System.out.println("HOUSE_STUDY_ALL_SIX_COMBINATION_RUNE_TYPES_24_QUANTITY_CASES_GREEDY_DEAD_END_SEARCH_MISSING_COSMIC_SHORT_CIRCUIT_AND_MAX_STACK_ATOMIC_OVERFLOW_OK");
 }
 public static void main(String[] args){try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Field boosts=io.xeros.content.boosts.Boosts.class.getDeclaredField("boosts");boosts.setAccessible(true);boosts.set(null,Collections.emptyList());furniture();tablets();runes();staffs();telescope();blueprint();runePlanner();System.out.println("HOUSE_STUDY_ALL_CHECKS_PASSED");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
